import { t as LanguageContext } from "./custom-language-BR14iqr3.mjs";
import { t as tscEmit } from "./tsc-CJA_TTZv.mjs";
import process from "node:process";
//#region src/tsc/worker.ts
process.on("message", (request) => {
	let response;
	try {
		const options = {
			...request.options,
			languageContext: new LanguageContext(request.options.languageContext.languages)
		};
		response = {
			id: request.id,
			result: tscEmit(options)
		};
	} catch (error) {
		response = {
			id: request.id,
			error
		};
	}
	process.send(response);
});
//#endregion
export {};
